targets.expr:
label_replace(
  (
    arista_bgp_peer_up{job=~"$job",switch=~"$switch",vrf=~"$vrf"}
      * on(job, switch, vrf, peer, asn)
        (1 - arista_bgp_peer_under_maintenance{job=~"$job",switch=~"$switch",vrf=~"$vrf"})
  )
  +
  (
    2 * arista_bgp_peer_under_maintenance{job=~"$job",switch=~"$switch",vrf=~"$vrf"}
  ),
  "address_family", "ipv4", "peer", ".*"
)
or
label_replace(
  (
    arista_bgp_evpn_peer_up{job=~"$job",switch=~"$switch",vrf=~"$vrf"}
      * on(job, switch, vrf, peer, asn)
        (1 - arista_bgp_evpn_peer_under_maintenance{job=~"$job",switch=~"$switch",vrf=~"$vrf"})
  )
  +
  (
    2 * arista_bgp_evpn_peer_under_maintenance{job=~"$job",switch=~"$switch",vrf=~"$vrf"}
  ),
  "address_family", "evpn", "peer", ".*"
)

arista_evpn_esi_forwarding_peers{job=~"$job",switch=~"$switch"}
  * on(job, switch, fabric, esi, evpn_instance)
    group_left(interface, redundancy_mode)
    arista_evpn_esi_info{job=~"$job",switch=~"$switch"}
